def transform(grid):
    """Complete four-panel motifs by reflecting matching color patterns."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    rows = [r for r in range(h) if len(set(grid[r])) == 1]
    cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    sep = Counter([grid[r][0] for r in rows] + [grid[0][c] for c in cols]).most_common(1)[0][0]
    rs = [-1] + [r for r in rows if grid[r][0] == sep] + [h]
    cs = [-1] + [c for c in cols if grid[0][c] == sep] + [w]
    rb = [(rs[i] + 1, rs[i+1]) for i in range(len(rs)-1)]
    cb = [(cs[i] + 1, cs[i+1]) for i in range(len(cs)-1)]
    out = [row[:] for row in grid]
    nrows, ncols = len(rb), len(cb)

    # Examine every adjacent 2x2 panel window. When a motif occurs in at least
    # two panels, use the observed reflection symmetry to complete its peers.
    for br in range(nrows - 1):
        for bc in range(ncols - 1):
            tiles = [(br,bc),(br,bc+1),(br+1,bc),(br+1,bc+1)]
            colors = {grid[r][c] for tr,tc in tiles
                      for r in range(*rb[tr]) for c in range(*cb[tc])
                      if grid[r][c] not in (0,sep)}
