                    grid[r][c] == color for r in range(*rb[tr]) for c in range(*cb[tc]))]
                if len(filled) < 2:
                    continue
                pairs = []
                # A full horizontal/vertical pair provides reflection evidence.
                for tr in (br,br+1):
                    left,right=(tr,bc),(tr,bc+1)
                    if left in filled and right in filled:
                        pairs.append((left,right,'x'))
                for tc in (bc,bc+1):
