def transform(grid):
    """Infer each color's paired panel columns from mirrored examples, then complete them."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    solid_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    solid_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    sep = Counter([grid[r][0] for r in solid_rows] + [grid[0][c] for c in solid_cols]).most_common(1)[0][0]
    rbounds = [-1] + [r for r in solid_rows if grid[r][0] == sep] + [h]
    cbounds = [-1] + [c for c in solid_cols if grid[0][c] == sep] + [w]
    row_panels = [(rbounds[i] + 1, rbounds[i + 1]) for i in range(len(rbounds) - 1)]
    col_panels = [(cbounds[i] + 1, cbounds[i + 1]) for i in range(len(cbounds) - 1)]
    out = [row[:] for row in grid]

    def pattern(rp, cp, color):
        ra, rb = row_panels[rp]
        ca, cb = col_panels[cp]
        return frozenset((r - ra, c - ca) for r in range(ra, rb)
                         for c in range(ca, cb) if grid[r][c] == color)

    # A known pair is evidenced by a color occupying two adjacent panels as
    # exact horizontal reflections in the same row band.
    pairs = {}
    colors = {v for row in grid for v in row if v not in (0, sep)}
    for color in colors:
        for rp in range(len(row_panels)):
            for cp in range(len(col_panels) - 1):
                a, b = pattern(rp, cp, color), pattern(rp, cp + 1, color)
                if not a or not b:
                    continue
                wa = col_panels[cp][1] - col_panels[cp][0]
                wb = col_panels[cp + 1][1] - col_panels[cp + 1][0]
                if wa != wb:
                    continue
                mirrored = frozenset((y, wa - 1 - x) for y, x in a)
                if mirrored == b:
                    pairs.setdefault(color, (cp, cp + 1))

    for color, (left, right) in pairs.items():
        for rp, (ra, rb) in enumerate(row_panels):
            a, b = pattern(rp, left, color), pattern(rp, right, color)
            if bool(a) == bool(b):
                continue
            src, dst = (left, right) if a else (right, left)
            srcpat = a if a else b
            dr, dc = row_panels[rp][0], col_panels[dst][0]
            width = col_panels[src][1] - col_panels[src][0]
            for y, x in srcpat:
                rr, cc = dr + y, dc + (width - 1 - x)
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                    out[rr][cc] = color
    return out
